import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const sourcePath = resolve(scriptDirectory, '../../../docs/cocrates/agent1.md');
const targetPath = resolve(scriptDirectory, '../src/browser/generated/cocrates-agent-system-prompt.ts');
const source = await readFile(sourcePath, 'utf8');

const generated = `/* eslint-disable */
// Generated from docs/cocrates/agent1.md. Do not edit this file directly.
import { BasePromptFragment } from '@theia/ai-core/lib/common';

export const COCRATES_SYSTEM_PROMPT_ID = 'cocrates-system';

export const cocratesSystemPrompt: BasePromptFragment = {
    id: COCRATES_SYSTEM_PROMPT_ID,
    template: ${JSON.stringify(source)},
};
`;

await mkdir(dirname(targetPath), { recursive: true });
await writeFile(targetPath, generated, 'utf8');
